f_i(x) = \begin{cases}
      i - \rho(x, \partial M_i), & x \in U(\partial M_i),\\
      i - 1 + \rho(x, \partial M_{i-1}), & x \in U(\partial M_{i-1}),\\
      F_i(x), & x \in M_i \setminus \mathop{\mathrm{Int}}M_{i-1}\setminus W(\partial M_i)\setminus W(\partial M_{i-1}),
   \end{cases}
